43	  int cacheIndex = threadIdx.x;
44	  cache[cacheIndex] = x[tid];
45	  __syncthreads();
46	  for (int i = 1; i < blockDim.x; i *= 2) {
47	    int index = 2 * i * cacheIndex;
48	    if (index < blockDim.x) {
49	      cache[index] += cache[index + i];
50	    }
51	    __syncthreads();
52	  }
53	  if (cacheIndex == 0)
54	  result[blockIdx.x] = cache[cacheIndex];
55	}
